'use client';

import { useRef } from 'react';
import { photoUrl } from '@/lib/api';
import { useT } from '@/lib/i18n/context';
import { ErrorMsg } from '@/components/ui';

// a photo slot: ready (has an id) or still being uploaded / generated by the AI
export type PhotoTile = { key: string; id?: string; status: 'ready' | 'uploading' | 'generating' };

export const MAX_PHOTOS = 10;

const tileStyle = {
  position: 'relative' as const,
  width: 104,
  height: 104,
  flex: '0 0 104px',
  borderRadius: 'var(--r-md)',
  overflow: 'hidden',
  border: '1px solid var(--stroke-2)',
  background: 'var(--glass-2)',
};

const iconBtn = {
  position: 'absolute' as const,
  width: 28,
  height: 28,
  borderRadius: '50%',
  border: 0,
  background: 'rgba(20,22,18,0.72)',
  color: '#fff',
  cursor: 'pointer',
  fontSize: 14,
  lineHeight: '28px',
  padding: 0,
};

// Dish photos: the first ready one is the main photo (shown on cards). Presentation only —
// the page decides whether changes go to the server right away or wait for "Save".
export default function PhotoEditor({
  tiles,
  onAdd,
  onRemove,
  onMakeMain,
  error,
}: {
  tiles: PhotoTile[];
  onAdd: (files: File[]) => void;
  onRemove: (key: string) => void;
  onMakeMain: (key: string) => void;
  error?: string | null;
}) {
  const { t } = useT();
  const input = useRef<HTMLInputElement>(null);
  const mainKey = tiles.find((x) => x.status === 'ready')?.key;
  const canAdd = tiles.length < MAX_PHOTOS;

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 10 }}>
        {tiles.map((tile) => (
          <div key={tile.key} style={tileStyle} data-testid="photo-tile">
            {tile.status === 'ready' && tile.id ? (
              // eslint-disable-next-line @next/next/no-img-element -- served by our API, already resized
              <img src={photoUrl(tile.id)} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block' }} />
            ) : (
              <div style={{ width: '100%', height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 8, textAlign: 'center', fontSize: 11, fontWeight: 700, color: 'var(--ink-2)' }} className="photo-pending">
                {tile.status === 'generating' ? t('food.photoGenerating') : t('food.photoUploading')}
              </div>
            )}

            {tile.status === 'ready' && tile.key === mainKey && (
              <span style={{ position: 'absolute', left: 6, bottom: 6, padding: '3px 8px', borderRadius: 'var(--r-pill)', background: 'var(--accent)', color: 'var(--accent-ink)', fontSize: 10, fontWeight: 800 }}>
                {t('food.photoMain')}
              </span>
            )}
            {tile.status === 'ready' && tile.key !== mainKey && (
              <button type="button" onClick={() => onMakeMain(tile.key)} aria-label={t('food.photoMakeMain')} title={t('food.photoMakeMain')} style={{ ...iconBtn, left: 6, bottom: 6 }}>
                ★
              </button>
            )}
            {tile.status === 'ready' && (
              <button type="button" onClick={() => onRemove(tile.key)} aria-label={t('food.photoRemove')} title={t('food.photoRemove')} style={{ ...iconBtn, right: 6, top: 6 }}>
                ×
              </button>
            )}
          </div>
        ))}

        {canAdd && (
          <button
            type="button"
            onClick={() => input.current?.click()}
            style={{ ...tileStyle, border: '1px dashed var(--stroke-2)', cursor: 'pointer', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 4, color: 'var(--ink-2)', fontFamily: 'inherit', fontSize: 12, fontWeight: 700 }}
          >
            <span style={{ fontSize: 24, lineHeight: 1 }}>+</span>
            {t('food.photoAdd')}
          </button>
        )}
        <input
          ref={input}
          type="file"
          accept="image/*"
          multiple
          hidden
          data-testid="photo-input"
          onChange={(e) => {
            const files = Array.from(e.target.files ?? []).slice(0, MAX_PHOTOS - tiles.length);
            e.target.value = ''; // the same file can be picked again after removing it
            if (files.length) onAdd(files);
          }}
        />
      </div>
      <span style={{ fontSize: 12, color: 'var(--ink-2)' }}>{t('food.photosHint')}</span>
      {error && <ErrorMsg>{error}</ErrorMsg>}
    </div>
  );
}
